package org.firstinspires.ftc.teamcode;

import com.qualcomm.hardware.rev.RevHubOrientationOnRobot;
import com.qualcomm.robotcore.eventloop.opmode.Autonomous;
import com.qualcomm.robotcore.eventloop.opmode.LinearOpMode;
import com.qualcomm.robotcore.hardware.DcMotor;
import com.qualcomm.robotcore.hardware.DcMotorEx;
import com.qualcomm.robotcore.hardware.DcMotorSimple;
import com.qualcomm.robotcore.hardware.IMU;
import com.qualcomm.robotcore.util.ElapsedTime;
import com.qualcomm.robotcore.util.Range;
import org.firstinspires.ftc.robotcore.external.navigation.AngleUnit;

/**
 * Generated by BIOBUZZ Auto Lab for the goBILDA 6WD drop-center StarterBot.
 * The constants below are the same numbers the simulator used, so the real robot runs
 * the same velocity profiles, turns and wall squares you planned. Re-export after you
 * change anything in the Robot panel or after calibration.
 *
 * Start pose in the sim: x=36.0 in, y=-60.0 in, heading=0.0 deg.
 * Simulated duration: see Auto Lab. Mechanisms (intake/launch) are stubs: wire them to the
 * goBILDA example code.
 */
@Autonomous(name = "BIOBUZZ Auto Lab", group = "Auto Lab")
public class BiobuzzAutoLab extends LinearOpMode {

    // ---- Robot model (keep identical to Auto Lab) ----
    static final double WHEEL_DIAMETER_IN = 4.0940;
    static final double TICKS_PER_REV     = 537.70;
    static final double GEAR_RATIO        = 1.0000;   // wheel turns per motor turn
    static final double DIST_SCALE        = 1.0000;   // from calibration
    static final double MAX_VEL_IN_S      = 56.85;       // 85% of free speed
    static final double MAX_ACCEL_IN_S2   = 60.0;
    static final double TRACK_EFF_IN      = 16.00;
    static final double START_HEADING_DEG = 0.0;
    static final double LAUNCH_SPINUP_S   = 0.80;
    static final double LAUNCH_PER_PIECE_S = 0.35;

    static final double TICKS_PER_IN = TICKS_PER_REV / (GEAR_RATIO * Math.PI * WHEEL_DIAMETER_IN) * DIST_SCALE;
    static final double HEADING_KP = 0.03;   // per degree, heading hold while driving
    static final double TURN_KP = 0.012;     // per degree
    static final double TURN_TOL_DEG = 1.0;

    private DcMotorEx[] left, right;
    private IMU imu;
    private double headingOffset = 0, targetHeading = START_HEADING_DEG;
    private final ElapsedTime matchTimer = new ElapsedTime();

    @Override
    public void runOpMode() {
        left = new DcMotorEx[]{hardwareMap.get(DcMotorEx.class, "left_drive")};
        right = new DcMotorEx[]{hardwareMap.get(DcMotorEx.class, "right_drive")};
        for (DcMotorEx m : left) m.setDirection(DcMotorSimple.Direction.REVERSE);
        for (DcMotorEx m : right) m.setDirection(DcMotorSimple.Direction.FORWARD);
        for (DcMotorEx m : all()) {
            m.setZeroPowerBehavior(DcMotor.ZeroPowerBehavior.BRAKE);
            m.setMode(DcMotor.RunMode.STOP_AND_RESET_ENCODER);
            m.setMode(DcMotor.RunMode.RUN_USING_ENCODER);
        }
        imu = hardwareMap.get(IMU.class, "imu");
        imu.initialize(new IMU.Parameters(new RevHubOrientationOnRobot(
                RevHubOrientationOnRobot.LogoFacingDirection.UP,
                RevHubOrientationOnRobot.UsbFacingDirection.FORWARD)));
        initMechanisms();

        telemetry.addLine("BIOBUZZ Auto Lab ready");
        telemetry.update();
        waitForStart();
        imu.resetYaw();
        headingOffset = START_HEADING_DEG;
        targetHeading = START_HEADING_DEG;
        matchTimer.reset();

        // ---- Plan (generated) ----
        drive(24.00, 0.80);  // leave start
        turnTo(45.0, 0.60);  // face the HIVE
        drive(6.00, 0.60);
        launch(4);  // preloaded POLLEN
        turnTo(0.0, 0.60);
        squareOnWall(-1, 0.35, 2000);  // back into audience wall to reset heading
        drive(20.00, 0.70);  // park

        stopDrive();
        telemetry.addData("Auto done in", "%.1f s", matchTimer.seconds());
        telemetry.update();
        while (opModeIsActive()) idle();
    }

    // ===================== Mechanisms: wire to goBILDA example code =====================
    private void initMechanisms() {
        // TODO: hardwareMap the intake and launcher exactly like the goBILDA StarterBot example code.
    }

    private void setIntake(boolean on) {
        // TODO: intake motor power on/off.
    }

    /** Fires n POLLEN. Keep the total time equal to LAUNCH_SPINUP_S + n * LAUNCH_PER_PIECE_S so sim timing matches. */
    private void launch(int n) {
        ElapsedTime t = new ElapsedTime();
        // TODO: spin up the launcher, feed n pieces, spin down.
        while (opModeIsActive() && t.seconds() < LAUNCH_SPINUP_S + n * LAUNCH_PER_PIECE_S) idle();
    }

    // ===================== Drive primitives (match the simulator) =====================
    private DcMotorEx[] all() {
        DcMotorEx[] a = new DcMotorEx[left.length + right.length];
        System.arraycopy(left, 0, a, 0, left.length);
        System.arraycopy(right, 0, a, left.length, right.length);
        return a;
    }

    private double heading() {
        return wrap(imu.getRobotYawPitchRollAngles().getYaw(AngleUnit.DEGREES) + headingOffset);
    }

    private static double wrap(double d) {
        while (d > 180) d -= 360;
        while (d <= -180) d += 360;
        return d;
    }

    private double leftInches() { double s = 0; for (DcMotorEx m : left) s += m.getCurrentPosition(); return s / left.length / TICKS_PER_IN; }
    private double rightInches() { double s = 0; for (DcMotorEx m : right) s += m.getCurrentPosition(); return s / right.length / TICKS_PER_IN; }

    private void setWheelVel(double leftInS, double rightInS) {
        for (DcMotorEx m : left) m.setVelocity(leftInS * TICKS_PER_IN);
        for (DcMotorEx m : right) m.setVelocity(rightInS * TICKS_PER_IN);
    }

    private void stopDrive() { setWheelVel(0, 0); }

    /** Trapezoidal-profile drive with IMU heading hold. Positive inches = forward. */
    private void drive(double inches, double power) {
        double vmax = MAX_VEL_IN_S * Range.clip(power, 0.05, 1.0);
        double dist = Math.abs(inches), sign = Math.signum(inches);
        double l0 = leftInches(), r0 = rightInches();
        ElapsedTime t = new ElapsedTime();
        double timeout = dist / vmax + vmax / MAX_ACCEL_IN_S2 + 1.5;
        while (opModeIsActive() && t.seconds() < timeout) {
            double traveled = Math.abs(((leftInches() - l0) + (rightInches() - r0)) / 2);
            double remaining = dist - traveled;
            if (remaining <= 0.25) break;
            double v = Math.min(vmax, Math.min(MAX_ACCEL_IN_S2 * t.seconds() + 4.0, Math.sqrt(2 * MAX_ACCEL_IN_S2 * remaining) + 1.0));
            double corr = HEADING_KP * wrap(targetHeading - heading()) * vmax;
            setWheelVel(sign * v - corr, sign * v + corr);
            idle();
        }
        stopDrive();
    }

    private void turnTo(double headingDeg, double power) {
        targetHeading = wrap(headingDeg);
        double wmax = MAX_VEL_IN_S * Range.clip(power, 0.05, 1.0);
        ElapsedTime t = new ElapsedTime();
        int settled = 0;
        while (opModeIsActive() && t.seconds() < 4.0) {
            double err = wrap(targetHeading - heading());
            if (Math.abs(err) < TURN_TOL_DEG) { if (++settled >= 5) break; } else settled = 0;
            double ramp = Math.min(1.0, MAX_ACCEL_IN_S2 * t.seconds() / wmax + 0.15);
            double v = Range.clip(TURN_KP * err * MAX_VEL_IN_S, -wmax, wmax) * ramp;
            if (Math.abs(v) < 3.0 && Math.abs(err) >= TURN_TOL_DEG) v = Math.signum(err) * 3.0;
            setWheelVel(-v, v);   // CCW positive
            idle();
        }
        stopDrive();
    }

    private void turnBy(double deg, double power) { turnTo(targetHeading + deg, power); }

    /** Drive into a wall at low power for ms, then trust the wall: snap heading to the nearest 90 deg. */
    private void squareOnWall(int dir, double power, long ms) {
        ElapsedTime t = new ElapsedTime();
        double v = dir * MAX_VEL_IN_S * Range.clip(power, 0.05, 1.0);
        while (opModeIsActive() && t.milliseconds() < ms) { setWheelVel(v, v); idle(); }
        stopDrive();
        sleep(100);
        double h = heading();
        double snap = Math.round(h / 90.0) * 90.0;
        if (Math.abs(wrap(h - snap)) < 20) { headingOffset += wrap(snap - h); targetHeading = snap; }
    }
}
